'use strict';
function spoonHint(name,f){const m=name.match(/^(.*?)\s*\(about ([½\d.]+) tsp per 2 portions\)$/);if(!m)return name;const b=m[2]==='½'?0.5:parseFloat(m[2]);const q=Math.round(b*f*4)/4;const w=Math.floor(q),fr={0.25:'¼',0.5:'½',0.75:'¾'}[+(q-w).toFixed(2)]||'';const t=(w?w:'')+fr||'¼';return m[1]+' (about '+t+' tsp)'}
const $=s=>document.querySelector(s),recipes=window.RECIPES;
let selected='SG',active=null,tab='ingredients',step=0,servings=2,complete=false,checked=new Set(),timer=null,toastTimeout;
const timers=new Map(),timerMinutes={},methodChoices={},hiddenVideos=new Set();
const flags={SG:'🇸🇬',JP:'🇯🇵',MX:'🇲🇽'};
function notify(t){if($('#recipe-dialog').open&&$('#dialog-status')){$('#dialog-status').textContent=t;setTimeout(()=>{if($('#dialog-status'))$('#dialog-status').textContent=''},6000);return}$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').style.display='none',6000)}
function recipe(id){return recipes.find(r=>r.id===id)}
function selectCountry(code,name){selected=code;const r=recipes.find(r=>r.code===code);$('#country-buttons').querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b.dataset.code===code);b.setAttribute('aria-pressed',String(b.dataset.code===code))});$('#map-land').querySelectorAll('path').forEach(p=>p.classList.toggle('selected',p.dataset.code===code));$('#map-pins').querySelectorAll('g').forEach(p=>p.classList.toggle('selected',p.dataset.code===code));if(!r){$('#country-panel').innerHTML='<div class="country-kicker">THE RECIPE ATLAS</div><h2 id="empty-country"></h2><p>We haven’t added recipes from this country yet. Explore one of our three pilot cuisines below the map.</p>';$('#empty-country').textContent=name;return}
$('#country-panel').innerHTML=`<div class="country-kicker"><span>${r.region}</span><span>01 RECIPE</span></div><h2>${r.flag} ${r.country}</h2><p>${r.intro}</p><img src="${r.image}" alt="${r.imageAlt}"><h3>${r.title}</h3><div class="meta"><span>◷ ${r.timeLabel||r.minutes+' min'}</span><span>2 portions</span><span>Guided</span></div><button class="primary" data-open="${r.id}">${r.visualGuide?'Start visual guide':'Explore recipe'}</button>`}
$('#country-buttons').innerHTML=recipes.map(r=>`<button data-code="${r.code}" aria-pressed="false">${r.flag} ${r.country}</button>`).join('');
$('#country-buttons').addEventListener('click',e=>{const b=e.target.closest('button');if(b)selectCountry(b.dataset.code)});
$('#recipe-grid').innerHTML=recipes.map(r=>`<article class="recipe-card"><button class="card-image" data-open="${r.id}" aria-label="Open ${r.title}"><img src="${r.image}" alt="${r.imageAlt}" loading="lazy"><span class="country-badge">${r.flag} ${r.country.toUpperCase()}</span></button><div class="card-body"><h3><button data-open="${r.id}">${r.title}</button></h3><div class="meta"><span>◷ ${r.timeLabel||r.minutes+' min'}</span><span>${r.nutrition.kcal} kcal / portion*</span></div><div class="card-foot"><span class="tag">${r.tag}</span><span>${r.visualGuide?'Video-led pilot':'Step-by-step'}</span></div></div></article>`).join('');
const ns='http://www.w3.org/2000/svg';
fetch('assets/map.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(countries=>{for(const c of countries){const p=document.createElementNS(ns,'path');p.setAttribute('d',c.d);p.dataset.code=c.code;const title=document.createElementNS(ns,'title');title.textContent=c.name+(recipes.some(r=>r.code===c.code)?' — recipe available':' — recipes not yet available');p.append(title);if(recipes.some(r=>r.code===c.code)){p.classList.add('available');p.setAttribute('tabindex','0');p.setAttribute('role','button');p.setAttribute('aria-label',c.name+' recipes');p.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();selectCountry(c.code,c.name)}})}p.addEventListener('click',()=>selectCountry(c.code,c.name));$('#map-land').append(p)}selectCountry(selected)}).catch(()=>{$('#map-error').hidden=false;$('#world').style.display='none'});
for(const r of recipes){const g=document.createElementNS(ns,'g'),c=document.createElementNS(ns,'circle'),t=document.createElementNS(ns,'text');g.dataset.code=r.code;g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label','Explore '+r.country);const x=(r.lon+180)*2.5,y=(85-r.lat)*2.65;c.setAttribute('cx',x);c.setAttribute('cy',y);c.setAttribute('r',5);t.setAttribute('x',x+12);t.setAttribute('y',y+5);t.textContent=r.country;g.append(c,t);g.addEventListener('click',()=>selectCountry(r.code));g.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();selectCountry(r.code)}});$('#map-pins').append(g)}
selectCountry('SG');
function openRecipe(id){const r=recipe(id);if(!r)throw Error('Unknown recipe');if(active?.id!==id){active=r;pantry=pantryByRecipe.get(id)||new Set();pantryByRecipe.set(id,pantry);step=0;servings=r.servings;tab=r.visualGuide?'cook':'ingredients';complete=false;checked=new Set()}renderRecipe();if(!$('#recipe-dialog').open)$('#recipe-dialog').showModal()}
function closeRecipe(){$('#recipe-dialog').close()}
function nutritionHTML(r){return Object.entries(r.nutrition).filter(([k])=>k!=='fibre').map(([k,v])=>`<div><b>${v}${k==='kcal'?'':'g'}</b><span>${k==='kcal'?'kcal':k} / portion</span></div>`).join('')+`<div><b>${r.nutrition.fibre}g</b><span>fibre / portion</span></div>`}
function renderRecipe(){const r=active;$('#recipe-dialog').classList.toggle('video-first',tab==='cook');$('#recipe-content').innerHTML=`<div class="dialog-top"><span class="dialog-recipe-name">${r.flag} ${escapeHTML(r.title)}</span><button class="text-button" data-action="active-timer" id="dialog-timer" hidden>Cooking timer</button><button class="close" data-action="close" aria-label="Close recipe">×</button></div><div id="dialog-status" role="status"></div><div class="recipe-head"><div><p class="eyebrow">${(r.timeLabel||r.minutes+' minutes').toUpperCase()} · ${r.tag.toUpperCase()}</p><h2 id="recipe-title">${r.title}</h2><p>${r.description}</p><div class="nutrition">${nutritionHTML(r)}</div><p class="image-note">*Illustrative nutrition estimates per portion${r.code==='MX'?' (two small burritos)':''}.</p>${r.sources?`<details class="recipe-provenance"><summary>Recipe sources & adaptations</summary><p>${escapeHTML(r.sourceNote)}</p>${r.sources.map(x=>`<a href="${escapeHTML(x.url)}" target="_blank" rel="noopener">${escapeHTML(x.label)}</a>`).join(' · ')}</details>`:''}</div><figure style="margin:0"><img src="${r.image}" alt="${r.imageAlt}"><figcaption class="image-note">Serving inspiration; not a photo of this exact recipe.</figcaption></figure></div><div class="recipe-tabs" role="tablist" aria-label="Recipe sections">${recipeTabs().map(([id,label])=>`<button role="tab" id="tab-${id}" aria-controls="tab-content" aria-selected="${tab===id}" tabindex="${tab===id?0:-1}" data-tab="${id}">${label}</button>`).join('')}</div><div id="tab-content" class="tab-content" role="tabpanel" aria-labelledby="tab-${tab}"></div>`;renderTab();updateFloatingTimer()}
function renderTab(){const r=active,el=$('#tab-content');if(tab==='costs'){renderCosts();return}if(tab==='prep'&&r.prepCards){el.innerHTML=`<div class="prep-grid">${r.prepCards.map(c=>`<article class="note-box"><h3>${escapeHTML(c.title)}</h3><p>${escapeHTML(c.text)}</p></article>`).join('')}</div><p class="method-sources"><a href="https://www.gov.uk/government/publications/home-food-fact-checker/home-food-fact-checker" target="_blank" rel="noopener">FSA: rice storage and reheating</a> · <a href="https://www.gov.uk/government/publications/food-safety-in-a-heatwave-advice-for-consumers/food-safety-in-a-heatwave-advice-for-consumers" target="_blank" rel="noopener">FSA: chilled transport</a></p>`;return}if(tab==='ingredients'){el.innerHTML=`<div class="ingredients-layout"><div><div class="servings-control"><strong>Ingredients</strong><div class="stepper"><button data-action="less" aria-label="Fewer portions" ${servings<=1?'disabled':''}>−</button><span>${servings} portion${servings===1?'':'s'}</span><button data-action="more" aria-label="More portions" ${servings>=8?'disabled':''}>+</button></div></div>${r.ingredients.map(([n,u,name],i)=>`<label class="ingredient"><input type="checkbox" data-ingredient="${i}" ${checked.has(i)?'checked':''}><span><b>${+(n*servings/r.servings).toFixed(1)} ${u}</b> ${spoonHint(name,servings/r.servings)}</span></label>`).join('')}</div><div class="note-box"><h3>Before you begin</h3>${r.equipment?`<p><strong>Equipment:</strong> ${escapeHTML(r.equipment)}</p>${r.timeNote?`<p>${escapeHTML(r.timeNote)}</p>`:''}`:''}<p>Check labels for allergens. Cook larger batches in stages.</p><p><strong>Allergens:</strong> ${r.allergens}</p><p><strong>Make it yours:</strong> ${r.swap}</p><button class="primary" data-tab="cook">Start cooking</button></div></div>`}else if(tab==='prep'){el.innerHTML=`<div class="prep-grid"><article class="note-box"><h3>01 / Portion first</h3><p>${r.prep}</p><p>Use clean, shallow containers and label them with the cooking date. This recipe makes ${servings} portion${servings===1?'':'s'} at your selected quantity.</p></article><article class="note-box"><h3>02 / Cool & store</h3><p>Refrigerate or freeze cooked food within 2 hours. Keep the fridge at 4°C or below. Cool rice promptly; do not leave a large pot standing at room temperature.</p><p>For this pilot, plan to eat refrigerated portions the next day. Freeze portions intended for later rather than assuming a full week in the fridge.</p></article><article class="note-box"><h3>03 / Reheat safely</h3><p>Reheat cooked portions until steaming hot all the way through. Stir where appropriate, check the centre and reheat only what you plan to eat. Keep cold salad and dressing out of the microwave.</p><p>Rice safety depends on prompt cooling and storage; reheating does not reliably remove toxins formed during unsafe storage.</p></article><article class="note-box"><h3>04 / Keep the balance</h3><p>Use wholegrains and include a variety of vegetables and protein. Fruit can be served alongside. Adjust portions for your appetite and needs.</p><p><a href="https://www.sfa.gov.sg/food-safety-tips/safe-food-practices/food-safety-tips" target="_blank" rel="noopener">Singapore Food Agency: food safety tips</a></p></article></div>`}else renderCook()}
function renderCook(){const el=$('#tab-content'),r=active;if(complete){el.innerHTML=`<div class="completion"><span class="seal">✓</span><h3>You made it.</h3><p>${servings} portion${servings===1?'':'s'}, and a little more confidence in the kitchen.</p><p>${r.code==='MX'?'For later meals, use the fresh-rice meal-prep route and store components separately. Reheated rice is for eating now.':'Eating later? Cool, portion and store promptly.'}</p><button class="primary" data-tab="prep">See meal-prep guidance</button><button class="secondary" data-action="restart">Review steps</button></div>`;return}renderVisualCook()}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function methodId(recipeId=active?.id,index=step){const base=recipe(recipeId)?.steps[index];return methodChoices[recipeId+':'+index]||base?.defaultMethod||'default'}
function activeStep(recipeId=active?.id,index=step){const base=recipe(recipeId)?.steps[index];return base?{...base,...base.methods?.find(m=>m.id===methodId(recipeId,index))}:null}
function methodHTML(s){return s.methods?`<fieldset class="method-picker"><legend>Cooking method</legend><div>${s.methods.map(m=>`<button data-method="${escapeHTML(m.id)}" aria-pressed="${m.id===methodId()}">${escapeHTML(m.label)}</button>`).join('')}</div></fieldset>`:''}
function chooseMethod(id){const base=active.steps[step];if(!base.methods?.some(m=>m.id===id)||id===methodId())return;const previous=currentTimer();if(previous?.running){previous.remaining=remaining(previous);previous.running=false}methodChoices[active.id+':'+step]=id;renderCook();updateFloatingTimer();$('[data-method="'+id+'"]')?.focus();if(previous)notify('Method changed. Your previous method’s timer is paused. Start this method only when you begin cooking it.')}
function activeDemo(){return activeStep()?.videos?.[0]||null}
function demoURL(v,embed=false){if(!v||!/^[-\w]{11}$/.test(v.id))throw Error('Invalid video');const url=new URL(embed?'https://www.youtube-nocookie.com/embed/'+v.id:'https://www.youtube.com/watch');if(!embed)url.searchParams.set('v',v.id);if(v.start)url.searchParams.set(embed?'start':'t',v.start);if(embed){url.searchParams.set('autoplay','1');url.searchParams.set('playsinline','1');if(Number.isInteger(v.end)&&v.end>v.start)url.searchParams.set('end',v.end)}return url.href}
function playDemo(){const v=activeDemo(),host=$('#step-video-player');if(!v||!host)return;const frame=document.createElement('iframe');frame.src=demoURL(v,true);frame.title=v.title+' — '+v.creator;frame.allow='autoplay; encrypted-media; picture-in-picture';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';host.replaceChildren(frame);host.focus();const replay=$('[data-action="replay-demo"]');if(replay)replay.hidden=false}
function techniqueHTML(s,v){
 if(!v)return '';
 return `<p class="video-scope">${escapeHTML(v.caption||v.scope||v.note)}</p><div class="step-video-player" id="step-video-player" tabindex="-1"><button class="load-demo" data-action="play-demo"><span class="play-symbol" aria-hidden="true">▶</span><strong>Play video</strong><span>${escapeHTML(v.title)}</span></button></div><div class="video-byline"><span>By ${escapeHTML(v.creator)}${v.kind==='reference'?' · Full reference':''}</span><button class="text-button" data-action="replay-demo" hidden>Replay</button><a href="${escapeHTML(demoURL(v))}" target="_blank" rel="noopener">Watch on YouTube</a></div>`;
}
function videoSectionHTML(s,v){const hidden=hiddenVideos.has(timerKey());return `<div class="video-section-heading"><h4 id="technique-heading">Technique video</h4><button class="text-button" data-action="toggle-video" aria-expanded="${!hidden}" aria-controls="technique-content">${hidden?'Show video':'Hide video'}</button></div><div id="technique-content" ${hidden?'hidden':''}>${hidden?'':techniqueHTML(s,v)}</div>`}
function toggleDemo(){const key=timerKey();hiddenVideos.has(key)?hiddenVideos.delete(key):hiddenVideos.add(key);const section=$('.technique-section');if(section)section.innerHTML=videoSectionHTML(activeStep(),activeDemo());$('[data-action="toggle-video"]')?.focus()}

function stepIngredients(s){return s.uses?.length?`<details class="step-more ingredient-disclosure"><summary>Ingredients for this step · ${servings} portion${servings===1?'':'s'}</summary><ul class="step-ingredients">${s.uses.map(i=>{const [n,u,name]=active.ingredients[i];return `<li>${escapeHTML(+(n*servings/active.servings).toFixed(1)+' '+u+' '+spoonHint(name,servings/active.servings))}</li>`}).join('')}</ul></details>`:''}
function stepNavigation(r){return `<div class="step-heading"><p class="step-count">Step ${step+1} of ${r.steps.length}</p><details class="steps-menu"><summary>All steps</summary><ol>${r.steps.map((item,i)=>`<li><button data-jump-step="${i}" ${i===step?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${escapeHTML(item.title)}</button></li>`).join('')}</ol></details></div>`}
function cookingTimerHTML(s){return s.seconds?`<section class="guide-section visual-timer" aria-labelledby="timer-heading"><h4 id="timer-heading">Timer</h4><p class="timer-label">${escapeHTML(s.timerLabel||'Cooking reminder')}</p>${s.adjustableTimer?`<label>Packet cooking time (minutes) <input type="number" id="timer-minutes" min="1" max="180" step="1" value="${timerMinutes[timerKey()]||s.seconds/60}" aria-label="Rice cooking time in minutes"></label>`:''}<div class="timer"><output id="timer-value" aria-label="Cooking time remaining">${formatTime((timerMinutes[timerKey()]||s.seconds/60)*60)}</output><button class="secondary" data-action="timer-toggle">Start timer</button><button class="text-button" data-action="timer-reset">Reset</button></div><p class="image-note">Check doneness when it rings. Keep this page open.</p></section>`:''}
function renderVisualCook(){
 const r=active,s=activeStep(),v=activeDemo();
 $('#tab-content').innerHTML=`<div class="visual-kitchen"><section class="visual-step" aria-labelledby="current-step-title">
 ${stepNavigation(r)}<h3 id="current-step-title" tabindex="-1">${escapeHTML(s.title)}</h3>
 ${s.methods?`<section class="guide-section cooking-method">${methodHTML(s)}</section>`:''}
 <section class="guide-section instructions-section" aria-labelledby="instructions-heading"><h4 id="instructions-heading">Instructions</h4><ol class="step-instruction concise-instructions">${(s.directions||[s.short||s.text]).map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ol>${stepIngredients(s)}</section>
 ${v?`<section class="guide-section technique-section" aria-labelledby="technique-heading">${videoSectionHTML(s,v)}</section>`:''}
 <section class="guide-section appearance-section" aria-labelledby="appearance-heading"><h4 id="appearance-heading">What it should look like</h4><div class="cue">${s.cueLabel||r.id==='ginger-chicken'&&step===5?`<b>${escapeHTML(s.cueLabel||'CHECK IT IS COOKED')}</b>`:''}<p>${escapeHTML(s.appearance||s.cue)}</p></div></section>
 ${cookingTimerHTML(s)}
 ${(s.sources?.length||v)?`<details class="step-more guide-extras"><summary>Sources</summary><div class="method-sources">${(s.sources||[]).map(source=>`<a href="${escapeHTML(source.url)}" target="_blank" rel="noopener">${escapeHTML(source.label)}</a>`).join('<br>')}${v?`<p><a href="${escapeHTML(v.sourceUrl)}" target="_blank" rel="noopener">${escapeHTML(v.creator)} · original video</a></p>`:''}</div></details>`:''}

 <div class="step-nav visual-nav"><button class="secondary" data-action="prev" ${step===0?'disabled':''}>Previous</button><span>${step+1} of ${r.steps.length}</span><button class="primary lime" data-action="next">${step===r.steps.length-1?'Finish & store':'Next step'}</button></div>
 </section></div>`;updateTimerUI()
}

function setTab(t){if(!recipeTabs().some(([id])=>id===t))return;tab=t;renderRecipe();$('#tab-'+t).focus()}
function formatTime(s){s=Math.max(0,s);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function timerKey(recipeId=active?.id,index=step){const id=methodId(recipeId,index),base=recipe(recipeId)?.steps[index];return recipeId+':'+index+(base?.methods&&id!==base.defaultMethod?':'+id:'')}
function currentTimer(){return timers.get(timerKey())||null}
function remaining(t=timer){return t?t.running?Math.max(0,Math.ceil((t.end-Date.now())/1000)):t.remaining:0}
function matchesTimer(){return !!currentTimer()}
function updateTimerUI(){const output=$('#timer-value'),t=currentTimer();if(!output||!t)return;output.textContent=formatTime(remaining(t));const b=$('[data-action="timer-toggle"]');if(b)b.textContent=t.running?'Pause':remaining(t)===0?'Restart timer':'Resume'}
function toggleTimer(){const s=activeStep();if(!s.seconds)return;let t=currentTimer();if(!t||remaining(t)===0){let seconds=s.seconds;if(active.visualGuide&&s.adjustableTimer){const value=Number($('#timer-minutes')?.value);if(!Number.isInteger(value)||value<1||value>180){notify('Choose a whole number from 1 to 180 minutes.');return}timerMinutes[timerKey()]=value;seconds=value*60}t={recipeId:active.id,step,method:methodId(),duration:seconds,checkpointDone:false,remaining:seconds,running:false,end:0};timers.set(timerKey(),t)}if(t.running){t.remaining=remaining(t);t.running=false}else{t.end=Date.now()+t.remaining*1000;t.running=true}timer=t;updateTimerUI();updateFloatingTimer()}
const floating=document.createElement('button');floating.id='floating-timer';floating.className='primary';floating.style.cssText='display:none;position:fixed;bottom:20px;right:20px;z-index:4;box-shadow:0 3px 20px #0003';
floating.addEventListener('click',()=>{const entries=[...timers.values()];if(!entries.length)return;const i=entries.indexOf(timer);timer=entries[(i+1)%entries.length];const target={...timer};openRecipe(target.recipeId);step=target.step;methodChoices[target.recipeId+':'+target.step]=target.method;complete=false;setTab('cook')});document.body.append(floating);
function updateFloatingTimer(){const entries=[...timers.values()];if(!entries.includes(timer))timer=entries[0]||null;const dt=$('#dialog-timer');if(dt){dt.hidden=!timer;if(timer)dt.textContent='◷ '+formatTime(remaining())+' · '+entries.length+' timer'+(entries.length===1?'':'s')+' (view)'}floating.style.display=timer?'block':'none';if(timer)floating.textContent='◷ '+formatTime(remaining())+' · '+entries.length+' timer'+(entries.length===1?'':'s');}
setInterval(()=>{for(const t of timers.values()){const base=recipe(t.recipeId).steps[t.step],s={...base,...base.methods?.find(m=>m.id===t.method)};if(t.running&&s.checkpointSeconds&&!t.checkpointDone&&remaining(t)>0&&t.duration-remaining(t)>=s.checkpointSeconds){t.checkpointDone=true;notify(s.checkpointMessage)}if(t.running&&remaining(t)===0){t.running=false;t.remaining=0;timer=t;notify(recipe(t.recipeId).steps[t.step].title+': timer finished. Check your food.')}}updateTimerUI();updateFloatingTimer()},500);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.method){chooseMethod(b.dataset.method);return}if(b.dataset.jumpStep!==undefined){step=Number(b.dataset.jumpStep);complete=false;renderCook();$('#current-step-title')?.focus();return}if(b.dataset.open){openRecipe(b.dataset.open);return}if(b.dataset.tab){setTab(b.dataset.tab);return}const action=b.dataset.action;if(!action)return;if(action==='toggle-video'){toggleDemo();return}if(action==='play-demo'||action==='replay-demo'){playDemo();return}if(action==='close')return closeRecipe();if(action==='active-timer'){floating.click();return}if(action==='more'||action==='less'){servings=Math.max(1,Math.min(8,servings+(action==='more'?1:-1)));renderTab();return}if(action==='prev'){step=Math.max(0,step-1);renderCook();$('#current-step-title')?.focus()}if(action==='next'){if(step===active.steps.length-1){complete=true}else step++;renderCook();$('#current-step-title')?.focus()}if(action==='restart'){complete=false;step=0;renderCook()}if(action==='timer-toggle')toggleTimer();if(action==='timer-reset'){if(matchesTimer()){timers.delete(timerKey());updateFloatingTimer()}renderCook()}if(action==='video'){$('#video-player').innerHTML='<iframe src="https://www.youtube-nocookie.com/embed/dCGS067s0zo?autoplay=1" title="Gordon Ramsay: how to chop an onion" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>';b.remove()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-pantry]')){const id=Number(e.target.dataset.pantry);e.target.checked?pantry.add(id):pantry.delete(id);renderCosts();document.querySelector('[data-pantry="'+id+'"]')?.focus();return}if(e.target.matches('[data-ingredient]')){const i=+e.target.dataset.ingredient;e.target.checked?checked.add(i):checked.delete(i)}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=recipeTabs().map(([id])=>id);let i=tabs.indexOf(tab);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;setTab(tabs[i])}});
$('#recipe-dialog').addEventListener('close',()=>{$('#video-player')?.replaceChildren();$('#step-video-player')?.replaceChildren()});
$('#credits-btn').addEventListener('click',()=>$('#credits-dialog').showModal());
$('#credits-body').innerHTML=`<p><strong>Health & food safety</strong><br><a href="https://www.healthhub.sg/programmes/nutrition-hub/eat-more" target="_blank" rel="noopener">HealthHub: My Healthy Plate</a><br><a href="https://www.sfa.gov.sg/tools-and-resources/glossary-a-z-on-food-safety" target="_blank" rel="noopener">SFA: food safety glossary</a><br><a href="https://www.sfa.gov.sg/food-safety-tips/food-risk-concerns/risk-at-a-glance/fried-rice-syndrome" target="_blank" rel="noopener">SFA: safe handling of cooked rice</a></p><p><a href="https://www.food.gov.uk/safety-hygiene/cooking-your-food" target="_blank" rel="noopener">Food Standards Agency: cooking and doneness checks</a></p><p><strong>About this pilot</strong><br>Original cuisine-inspired recipe drafts. Nutrition numbers are illustrative estimates, not suitable for clinical dietary planning. Photographs show related dishes, not these exact recipes. Technique media is an independent public reference; no creator partnership is implied.</p><p><strong>Photographs</strong><br><a href="https://commons.wikimedia.org/wiki/File:Donburi_Rice_bowl_of_Chicken_Teriyaki_with_Tomato.jpg" target="_blank" rel="noopener">Chicken rice bowl — TechnoKittyCat</a>, CC0.<br><a href="https://commons.wikimedia.org/wiki/File:Salmon_with_Rice_and_Sauce_finished_dish.jpg" target="_blank" rel="noopener">Salmon with rice — Datariumrex</a>, CC0.<br><a href="https://commons.wikimedia.org/wiki/File:Day_244-_Chicken_Burrito_(8038319026).jpg" target="_blank" rel="noopener">Chicken burrito — Sodanie Chea</a>, <a href="https://creativecommons.org/licenses/by/2.0/" target="_blank" rel="noopener">CC BY 2.0</a>. Images resized and cropped for display.</p><p><strong>Ginger chicken technique videos</strong><br>Learn To Cook / Chef Mark; Iowa State University Extension; Jamie Oliver; Laura Fuentes; Spice N’ Pans; Foods101withDeronda. Short demonstrations and optional full references are labelled separately. Rice-cooker method: Zojirushi’s brown-rice guide. Each step links its original source. These are independent technique references, not footage of this exact recipe.</p><p><strong>Chicken & cheese burrito</strong><br>Recipe inspiration: Anna Glover / Good Food. Pan method: Good Food; air fryer: Bored of Lunch. Short technique references: Nick’s Kitchen (pepper preparation), Twisted (folding). Chicken cutting: MOMables / Laura Fuentes. Sources and adaptations are linked in the recipe. No beans; our own amounts and consistent preparation sequence apply.</p><p><strong>Sesame salmon rice bowl</strong><br>Quick-bowl inspiration: Good Food / Helena Busiakiewicz. Air-fryer technique: Downshiftology / Lisa Bryan; oven: Good Food / Lulu Grimes. Ginger peeling: Jamie Oliver. Vegetable references are credited within their steps. Our amounts and clean finishing dressing apply.</p><p><strong>Map</strong><br>Natural Earth country geometry via <a href="https://github.com/datasets/geo-countries" target="_blank" rel="noopener">DataHub geo-countries</a>, public-domain Natural Earth data. Simplified for display; boundaries are illustrative.</p>`;
if(document.modelContext?.registerTool){for(const tool of [{name:'list_recipes',description:'Read the pilot recipe collection.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>recipes.map(({id,country,title,minutes})=>({id,country,title,minutes}))},{name:'open_recipe',description:'Open a recipe guide. Does not mark it cooked.',inputSchema:{type:'object',properties:{recipe_id:{type:'string'}},required:['recipe_id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.recipe_id!=='string'||!recipe(input.recipe_id))throw Error('Unknown recipe');openRecipe(input.recipe_id);return {opened:input.recipe_id,section:tab}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}

/* ===== Kitchen helpers: alarm, screen-awake, saved progress, glossary ===== */
const baseTitle=document.title;let actx=null,wl=null;
const store={get(k){try{return JSON.parse(localStorage.getItem('hc:'+k))}catch{return null}},set(k,v){try{localStorage.setItem('hc:'+k,JSON.stringify(v))}catch{}}};
function primeAudio(){try{actx=actx||new(window.AudioContext||window.webkitAudioContext)();if(actx.state==='suspended')actx.resume()}catch{}}
function alarm(){try{primeAudio();[0,.4,.8].forEach(d=>{const o=actx.createOscillator(),g=actx.createGain();o.frequency.value=880;g.gain.value=.25;o.connect(g);g.connect(actx.destination);o.start(actx.currentTime+d);o.stop(actx.currentTime+d+.22)})}catch{}try{navigator.vibrate&&navigator.vibrate([300,150,300,150,300])}catch{}document.title='⏰ Timer done · healthycooks'}
const _notify=notify;notify=function(t){_notify(t);if(/timer finished/i.test(String(t)))alarm()};
async function keepAwake(on){try{if(on&&navigator.wakeLock&&!wl){wl=await navigator.wakeLock.request('screen');wl.addEventListener('release',()=>{wl=null})}else if(!on&&wl){await wl.release();wl=null}}catch{}}
function saveProgress(){if(!active)return;store.set(active.id,{step,servings,checked:[...checked]})}
const _openRecipe=openRecipe;
openRecipe=function(id){const fresh=active?.id!==id;_openRecipe(id);if(fresh){const s=store.get(id);if(s&&Number.isInteger(s.step)&&s.step>=0&&s.step<active.steps.length){step=s.step;servings=Math.min(8,Math.max(1,Number(s.servings)||servings));checked=new Set(Array.isArray(s.checked)?s.checked:[]);renderRecipe()}}};
const GLOSSARY=`<details class="step-more glossary"><summary>Cooking words explained</summary><ul><li><b>Boil:</b> big bubbles constantly breaking the surface. <b>Simmer:</b> small bubbles gently rising, not a rolling boil.</li><li><b>Low heat:</b> barely sizzles. <b>Medium heat:</b> food sizzles gently when it touches the pan. <b>High heat:</b> loud sizzle and it can scorch, so stay beside the pan. Hob dials differ, so go by what you see and hear.</li><li><b>A splash of water:</b> about 1–2 tablespoons.</li><li><b>Short bursts (microwave):</b> 30 seconds at a time, then stir.</li><li><b>Uncrowded layer:</b> pieces not touching or stacked, so they brown instead of steaming.</li><li><b>Fork-check:</b> push a fork into the thickest part. It should slide in with gentle resistance.</li><li><b>Fluff rice:</b> loosen the grains with a fork.</li></ul></details>`;
const _renderVisualCook=renderVisualCook;
renderVisualCook=function(){_renderVisualCook();const nav=$('.visual-step .step-nav');if(nav&&!$('.glossary'))nav.insertAdjacentHTML('beforebegin',GLOSSARY)};
document.addEventListener('click',e=>{if(e.target.closest('[data-action="timer-toggle"]'))primeAudio();document.title=baseTitle;if($('#recipe-dialog').open&&tab==='cook')keepAwake(true);setTimeout(saveProgress,0)});
document.addEventListener('change',()=>setTimeout(saveProgress,0));
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&$('#recipe-dialog').open&&tab==='cook')keepAwake(true)});
$('#recipe-dialog').addEventListener('close',()=>keepAwake(false));

/* ===== Rice fallback, start over, printable shopping list ===== */
const RICE_NOTE=`<p class="rice-fallback"><b>No packet?</b> Use the packet if you have it. Otherwise, for long-grain brown rice use 1 cup rice to 2 cups water, bring to a simmer, cover and cook 40–45 minutes. For long-grain white rice use 1 cup rice to 1½ cups water and cook about 12–15 minutes. Rest covered for 5–10 minutes, then fluff with a fork.</p>`;
const _renderVisualCook2=renderVisualCook;
renderVisualCook=function(){_renderVisualCook2();const sec=$('.instructions-section'),s=activeStep();if(sec&&s&&/packet/i.test(JSON.stringify([s.directions,s.short,s.text]))&&!sec.querySelector('.rice-fallback'))sec.insertAdjacentHTML('beforeend',RICE_NOTE);const g=$('.glossary');if(g&&!$('[data-action="start-over"]'))g.insertAdjacentHTML('afterend','<p class="start-over"><button class="text-button" data-action="start-over">Start this recipe over</button></p>')};
const _renderTab=renderTab;
renderTab=function(){_renderTab();if(tab==='ingredients'){const c=$('.servings-control');if(c&&!$('.print-btn'))c.insertAdjacentHTML('afterend',`<h2 class="print-only">${escapeHTML(active.title)} · ${servings} portion${servings===1?'':'s'}</h2><button class="text-button print-btn" data-action="print-list">Print or save shopping list</button>`)}};
document.addEventListener('click',e=>{if(e.target.closest('[data-action="print-list"]')){window.print();return}if(e.target.closest('[data-action="start-over"]')&&active){step=0;servings=active.servings;checked=new Set();complete=false;try{localStorage.removeItem('hc:'+active.id)}catch{}renderRecipe();notify('Started over from step 1.')}});

/* ===== Price note + dark mode toggle ===== */
const _renderCosts=renderCosts;
renderCosts=function(){_renderCosts();const s=document.querySelector('.cost-section');if(s&&!s.querySelector('.price-note'))s.insertAdjacentHTML('beforeend','<p class="price-note image-note">Prices are estimates based on regular FairPrice listings and change often. Promotions, other stores and pack sizes can make your actual cost higher or lower.</p>')};
(function(){const root=document.documentElement;try{if(localStorage.getItem('hc:theme')==='dark')root.dataset.theme='dark'}catch{}
const b=document.createElement('button');b.type='button';b.className='text-button theme-toggle';
const label=()=>{const d=root.dataset.theme==='dark';b.textContent=d?'☀ Light mode':'☾ Dark mode';b.setAttribute('aria-pressed',String(d))};
b.addEventListener('click',()=>{const d=root.dataset.theme==='dark';if(d)delete root.dataset.theme;else root.dataset.theme='dark';try{localStorage.setItem('hc:theme',d?'light':'dark')}catch{}label()});
label();const ed=document.querySelector('header .edition');if(ed)ed.parentNode.insertBefore(b,ed);else document.body.prepend(b)})();